#!/usr/bin/env python3
from pathlib import Path

ROOT = Path.cwd()
comp = ROOT / "frontend" / "components" / "SignalsClient.tsx"
css_path = ROOT / "frontend" / "app" / "globals.css"

if not comp.exists():
    raise SystemExit("❌ 找不到 frontend/components/SignalsClient.tsx，請在 repo 根目錄執行。")
if not css_path.exists():
    raise SystemExit("❌ 找不到 frontend/app/globals.css，請在 repo 根目錄執行。")

bak = comp.with_suffix(comp.suffix + ".bak_v106")
if not bak.exists():
    bak.write_text(comp.read_text(encoding="utf-8"), encoding="utf-8")

comp.write_text('\'use client\';\n\nimport { useMemo, useState } from \'react\';\n\ntype AnyRow = Record<string, any>;\ntype SortKey = \'amount\' | \'lots\' | \'consensus\' | \'price\' | \'pct\' | \'status\';\ntype SortDir = \'asc\' | \'desc\';\n\nconst STATUS_ORDER: Record<string, number> = {\n  新增: 1,\n  加碼: 2,\n  減碼: 3,\n  刪除: 4,\n  異動: 5,\n};\n\nfunction num(v: any, fallback = 0): number {\n  if (v === null || v === undefined || v === \'\') return fallback;\n  const x = Number(String(v).replace(/,/g, \'\').replace(/[^\\d.-]/g, \'\'));\n  return Number.isFinite(x) ? x : fallback;\n}\n\nfunction firstNum(row: AnyRow, keys: string[], fallback = 0): number {\n  for (const k of keys) {\n    if (row && row[k] !== undefined && row[k] !== null && row[k] !== \'\') {\n      const v = num(row[k], NaN);\n      if (Number.isFinite(v)) return v;\n    }\n  }\n  return fallback;\n}\n\nfunction getRows(data: any): AnyRow[] {\n  const src = data?.rows ?? data?.changes ?? data?.aggregate ?? data?.items ?? [];\n  return Array.isArray(src) ? src : [];\n}\n\nfunction getCode(row: AnyRow): string {\n  return String(row.stock_code ?? row.code ?? \'\').trim();\n}\n\nfunction getName(row: AnyRow): string {\n  return String(row.stock_name ?? row.name ?? row.stockName ?? getCode(row)).trim();\n}\n\nfunction getPrice(row: AnyRow): number | null {\n  const v = firstNum(row, [\'price\', \'close_price\', \'close\', \'last_price\'], NaN);\n  return Number.isFinite(v) ? v : null;\n}\n\nfunction getPct(row: AnyRow): number | null {\n  const v = firstNum(row, [\'change_pct\', \'pct\', \'percent\', \'changePercent\'], NaN);\n  return Number.isFinite(v) ? v : null;\n}\n\nfunction getLots(row: AnyRow): number {\n  let v = firstNum(row, [\n    \'net_lots\',\n    \'display_delta_lots\',\n    \'change_lots\',\n    \'delta_lots\',\n    \'lot_change\',\n    \'shares_change\',\n    \'delta_shares\',\n  ], 0);\n\n  // 若來源仍是「股」，轉成「張」\n  if (Math.abs(v) >= 100000) v = v / 1000;\n  return v;\n}\n\nfunction getAmountBillion(row: AnyRow): number {\n  const v = firstNum(row, [\n    \'flow_billion\',\n    \'money_billion\',\n    \'amount_billion\',\n    \'delta_amount_billion\',\n    \'delta_value_billion\',\n    \'net_amount_billion\',\n    \'trade_amount_billion\',\n  ], NaN);\n\n  if (Number.isFinite(v)) return v;\n\n  const price = getPrice(row);\n  const lots = getLots(row);\n  if (price !== null && Number.isFinite(lots)) {\n    return price * lots * 1000 / 100000000;\n  }\n\n  return 0;\n}\n\nfunction rowStatus(row: AnyRow): string {\n  const s = String(row.status ?? row.type ?? \'\').trim();\n  if (s) return s;\n  const lots = getLots(row);\n  if (lots > 0) return \'加碼\';\n  if (lots < 0) return \'減碼\';\n  return \'異動\';\n}\n\nfunction getBuyCount(row: AnyRow): number {\n  const direct = firstNum(row, [\'add_etf_count\', \'add_count\', \'buy_count\', \'buy_etf_count\', \'increase_count\'], NaN);\n  if (Number.isFinite(direct)) return Math.max(0, Math.round(direct));\n\n  const status = rowStatus(row);\n  const etfCount = Math.max(0, Math.round(firstNum(row, [\'etf_count\', \'count\'], 0)));\n  return status === \'新增\' || status === \'加碼\' ? etfCount : 0;\n}\n\nfunction getSellCount(row: AnyRow): number {\n  const direct = firstNum(row, [\'reduce_etf_count\', \'sell_count\', \'sell_etf_count\', \'decrease_count\'], NaN);\n  if (Number.isFinite(direct)) return Math.max(0, Math.round(direct));\n\n  const status = rowStatus(row);\n  const etfCount = Math.max(0, Math.round(firstNum(row, [\'etf_count\', \'count\'], 0)));\n  return status === \'刪除\' || status === \'減碼\' ? etfCount : 0;\n}\n\nfunction getConsensusScore(row: AnyRow): number {\n  return getBuyCount(row) - getSellCount(row);\n}\n\nfunction mmdd(dateLike: any): string {\n  const s = String(dateLike ?? \'\').trim();\n  const m = s.match(/(\\d{4})-(\\d{2})-(\\d{2})/);\n  if (m) return `${m[2]}-${m[3]}`;\n  return s;\n}\n\nfunction fmt0(v: any): string {\n  const x = num(v, NaN);\n  if (!Number.isFinite(x)) return \'-\';\n  return Math.round(x).toLocaleString(\'zh-TW\');\n}\n\nfunction fmtPrice(v: number | null): string {\n  if (v === null || !Number.isFinite(v)) return \'-\';\n  return v.toLocaleString(\'zh-TW\', { maximumFractionDigits: v >= 100 ? 1 : 2 });\n}\n\nfunction fmtPct(v: number | null): string {\n  if (v === null || !Number.isFinite(v)) return \'-\';\n  const sign = v > 0 ? \'+\' : \'\';\n  return `${sign}${v.toFixed(2)}%`;\n}\n\nfunction fmtSigned(v: number, suffix = \'\'): string {\n  if (!Number.isFinite(v)) return \'-\';\n  if (Math.abs(v) < 0.01) return `0${suffix}`;\n  const sign = v > 0 ? \'+\' : \'\';\n  return `${sign}${Math.round(v).toLocaleString(\'zh-TW\')}${suffix}`;\n}\n\nfunction fmtBillion(v: number): string {\n  if (!Number.isFinite(v)) return \'-\';\n  const sign = v > 0 ? \'+\' : \'\';\n  const abs = Math.abs(v);\n  const digits = abs >= 100 ? 1 : abs >= 10 ? 1 : 2;\n  return `${sign}${v.toLocaleString(\'zh-TW\', { minimumFractionDigits: 0, maximumFractionDigits: digits })}億`;\n}\n\nfunction toneByValue(v: number): \'up\' | \'down\' | \'flat\' {\n  if (v > 0) return \'up\';\n  if (v < 0) return \'down\';\n  return \'flat\';\n}\n\nfunction FocusCard({ title, item, tone }: { title: string; item?: AnyRow | null; tone: \'red\' | \'green\' }) {\n  if (!item) {\n    return (\n      <div className={`signal106-focus ${tone}`}>\n        <div className="signal106-focus-title">{title}</div>\n        <div className="signal106-empty">尚無有效訊號</div>\n      </div>\n    );\n  }\n\n  const price = getPrice(item);\n  const pct = getPct(item);\n  const lots = getLots(item);\n  const amount = getAmountBillion(item);\n  const buy = getBuyCount(item);\n  const sell = getSellCount(item);\n\n  return (\n    <div className={`signal106-focus ${tone}`}>\n      <div className="signal106-focus-title">{title}</div>\n      <div className="signal106-focus-name">\n        <span>{getName(item)}</span>\n        <b>{getCode(item)}</b>\n      </div>\n      <div className="signal106-focus-price">\n        {fmtPrice(price)} <span className={toneByValue(pct ?? 0)}>{fmtPct(pct)}</span>\n      </div>\n      <div className="signal106-focus-sub">\n        <span>淨額 <b className={toneByValue(amount)}>{fmtBillion(amount)}</b></span>\n        <span>張數 <b className={toneByValue(lots)}>{fmtSigned(lots, \'張\')}</b></span>\n        <span>買賣 <b>{buy}:{sell}</b></span>\n      </div>\n    </div>\n  );\n}\n\nfunction SortPill({\n  label,\n  sortKey,\n  activeKey,\n  dir,\n  onClick,\n}: {\n  label: string;\n  sortKey: SortKey;\n  activeKey: SortKey;\n  dir: SortDir;\n  onClick: (key: SortKey) => void;\n}) {\n  const active = activeKey === sortKey;\n  return (\n    <button className={`signal106-pill sort ${active ? \'active\' : \'\'}`} onClick={() => onClick(sortKey)} type="button">\n      {label} {active ? (dir === \'desc\' ? \'↓\' : \'↑\') : \'↕\'}\n    </button>\n  );\n}\n\nfunction StatusPill({\n  label,\n  active,\n  count,\n  onClick,\n}: {\n  label: string;\n  active: boolean;\n  count: number;\n  onClick: () => void;\n}) {\n  return (\n    <button className={`signal106-pill status ${label} ${active ? \'active\' : \'\'}`} onClick={onClick} type="button">\n      {label}<b>{count || 0}</b>\n    </button>\n  );\n}\n\nfunction SignalRow({ row }: { row: AnyRow }) {\n  const status = rowStatus(row);\n  const price = getPrice(row);\n  const pct = getPct(row);\n  const amount = getAmountBillion(row);\n  const lots = getLots(row);\n  const buy = getBuyCount(row);\n  const sell = getSellCount(row);\n\n  return (\n    <div className="signal106-row">\n      <div className="signal106-cell stock">\n        <b>{getName(row)}</b>\n        <span>{getCode(row)}</span>\n      </div>\n\n      <div className="signal106-cell quote">\n        <b>{fmtPrice(price)}</b>\n        <span className={toneByValue(pct ?? 0)}>{fmtPct(pct)}</span>\n      </div>\n\n      <div className="signal106-cell trade">\n        <b className={toneByValue(amount)}>{fmtBillion(amount)}</b>\n        <span className={toneByValue(lots)}>{fmtSigned(lots, \'張\')}</span>\n      </div>\n\n      <div className="signal106-cell action">\n        <span className={`signal106-status ${status}`}>{status}</span>\n        <em>買賣 {buy}:{sell}</em>\n      </div>\n    </div>\n  );\n}\n\nexport default function SignalsClient(props: any) {\n  const data = props?.data ?? props ?? {};\n  const sourceRows = getRows(data);\n\n  const [selectedStatuses, setSelectedStatuses] = useState<string[]>([\'新增\', \'刪除\', \'加碼\', \'減碼\']);\n  const [sortKey, setSortKey] = useState<SortKey>(\'amount\');\n  const [sortDir, setSortDir] = useState<SortDir>(\'desc\');\n\n  const rows = useMemo(() => {\n    const filtered = sourceRows.filter((r) => selectedStatuses.includes(rowStatus(r)));\n\n    const valueOf = (r: AnyRow) => {\n      switch (sortKey) {\n        case \'amount\':\n          // V106 修正：金額排序用「有正負號的淨額」，不是絕對值。\n          // 因此金額↓ = 流入最多在前；金額↑ = 流出最多在前。\n          return getAmountBillion(r);\n        case \'lots\':\n          // 張數同樣用正負號；張數↓ = 加碼最多，張數↑ = 減碼最多。\n          return getLots(r);\n        case \'consensus\':\n          // 共識 = 買方 ETF 檔數 - 賣方 ETF 檔數。\n          return getConsensusScore(r);\n        case \'price\':\n          return getPrice(r) ?? -Infinity;\n        case \'pct\':\n          return getPct(r) ?? -Infinity;\n        case \'status\':\n          return STATUS_ORDER[rowStatus(r)] ?? 99;\n        default:\n          return 0;\n      }\n    };\n\n    return [...filtered].sort((a, b) => {\n      const av = valueOf(a);\n      const bv = valueOf(b);\n      return sortDir === \'desc\' ? bv - av : av - bv;\n    });\n  }, [sourceRows, selectedStatuses, sortKey, sortDir]);\n\n  const summary = useMemo(() => {\n    const out: Record<string, number> = { 新增: 0, 刪除: 0, 加碼: 0, 減碼: 0 };\n    for (const r of sourceRows) {\n      const s = rowStatus(r);\n      if (out[s] !== undefined) out[s] += 1;\n    }\n    return out;\n  }, [sourceRows]);\n\n  const focus = useMemo(() => {\n    const usable = sourceRows.filter((r) => rowStatus(r) !== \'異動\');\n    const positive = usable.filter((r) => getAmountBillion(r) > 0);\n    const negative = usable.filter((r) => getAmountBillion(r) < 0);\n    const addLike = usable.filter((r) => [\'新增\', \'加碼\'].includes(rowStatus(r)));\n    const reduceLike = usable.filter((r) => [\'刪除\', \'減碼\'].includes(rowStatus(r)));\n\n    const maxBy = (arr: AnyRow[], fn: (x: AnyRow) => number) =>\n      arr.length ? [...arr].sort((a, b) => fn(b) - fn(a))[0] : null;\n\n    const minBy = (arr: AnyRow[], fn: (x: AnyRow) => number) =>\n      arr.length ? [...arr].sort((a, b) => fn(a) - fn(b))[0] : null;\n\n    return {\n      inflow: maxBy(positive, getAmountBillion),\n      outflow: minBy(negative, getAmountBillion),\n      mostAdd: maxBy(addLike, (r) => getBuyCount(r) * 1000000 + getLots(r)),\n      mostReduce: maxBy(reduceLike, (r) => getSellCount(r) * 1000000 + Math.abs(getLots(r))),\n    };\n  }, [sourceRows]);\n\n  const dataDate = data?.data_date ?? data?.latestDataDate ?? \'\';\n  const fetched = data?.fetched_etf_count ?? data?.includedEtfCount ?? 0;\n  const total = data?.total_etf_count ?? data?.totalEtfCount ?? 0;\n\n  function toggleStatus(s: string) {\n    setSelectedStatuses((prev) => {\n      if (prev.includes(s)) return prev.filter((x) => x !== s);\n      return [...prev, s];\n    });\n  }\n\n  function toggleSort(k: SortKey) {\n    if (sortKey === k) {\n      setSortDir((d) => (d === \'desc\' ? \'asc\' : \'desc\'));\n    } else {\n      setSortKey(k);\n      setSortDir(\'desc\');\n    }\n  }\n\n  return (\n    <main className="page signals-v7-page signal106-page">\n      <div className="signals-title-block signal106-title-block">\n        <h2>今日訊號</h2>\n        <div className="signals-data-status ok">\n          已抓取 {fetched || total || 0} / {total || fetched || 0} 檔 ETF\n          {dataDate ? `，資料日期 ${mmdd(dataDate)}` : \'\'}\n        </div>\n      </div>\n\n      <div className="signal106-focus-grid">\n        <FocusCard title="淨資金流入最多" item={focus.inflow} tone="red" />\n        <FocusCard title="淨資金流出最多" item={focus.outflow} tone="green" />\n        <FocusCard title="最多 ETF 加碼" item={focus.mostAdd} tone="red" />\n        <FocusCard title="最多 ETF 減碼" item={focus.mostReduce} tone="green" />\n      </div>\n\n      <section className="signal106-detail">\n        <h3>資金交易明細：共 {fmt0(rows.length)} 檔</h3>\n\n        <div className="signal106-pill-row">\n          <StatusPill label="新增" active={selectedStatuses.includes(\'新增\')} count={summary[\'新增\']} onClick={() => toggleStatus(\'新增\')} />\n          <StatusPill label="刪除" active={selectedStatuses.includes(\'刪除\')} count={summary[\'刪除\']} onClick={() => toggleStatus(\'刪除\')} />\n          <StatusPill label="加碼" active={selectedStatuses.includes(\'加碼\')} count={summary[\'加碼\']} onClick={() => toggleStatus(\'加碼\')} />\n          <StatusPill label="減碼" active={selectedStatuses.includes(\'減碼\')} count={summary[\'減碼\']} onClick={() => toggleStatus(\'減碼\')} />\n        </div>\n\n        <div className="signal106-pill-row sortrow">\n          <SortPill label="金額" sortKey="amount" activeKey={sortKey} dir={sortDir} onClick={toggleSort} />\n          <SortPill label="張數" sortKey="lots" activeKey={sortKey} dir={sortDir} onClick={toggleSort} />\n          <SortPill label="共識" sortKey="consensus" activeKey={sortKey} dir={sortDir} onClick={toggleSort} />\n          <SortPill label="股價" sortKey="price" activeKey={sortKey} dir={sortDir} onClick={toggleSort} />\n          <SortPill label="漲跌幅" sortKey="pct" activeKey={sortKey} dir={sortDir} onClick={toggleSort} />\n          <SortPill label="狀態" sortKey="status" activeKey={sortKey} dir={sortDir} onClick={toggleSort} />\n        </div>\n\n        <div className="signal106-header">\n          <span>標的</span>\n          <span>股價</span>\n          <span>淨額 / 張數</span>\n          <span>狀態 / 共識</span>\n        </div>\n\n        <div className="signal106-list">\n          {rows.length ? rows.map((row, idx) => <SignalRow key={`${getCode(row)}-${idx}`} row={row} />) : (\n            <div className="signal106-empty-list">目前沒有符合篩選的訊號。</div>\n          )}\n        </div>\n      </section>\n    </main>\n  );\n}\n', encoding="utf-8")

css = css_path.read_text(encoding="utf-8")
marker = "/* ===== V106 signal page: signed amount sorting + cleaner table list ===== */"
if marker not in css:
    css_path.write_text(css.rstrip() + "\n\n" + '\n/* ===== V106 signal page: signed amount sorting + cleaner table list ===== */\n.signal106-page {\n  padding-left: max(16px, env(safe-area-inset-left));\n  padding-right: max(16px, env(safe-area-inset-right));\n}\n\n.signal106-page .signal103-range,\n.signal106-page .signal103-label,\n.signal106-page .signal103-range-tabs,\n.signal106-page .signal104-focus-grid,\n.signal106-page .signal104-detail,\n.signal106-page .signal104-row,\n.signal106-page .signal104-list,\n.signal106-page .signal105-focus-grid,\n.signal106-page .signal105-detail,\n.signal106-page .signal105-row,\n.signal106-page .signal105-list {\n  display: none !important;\n}\n\n.signal106-title-block h2 {\n  font-size: clamp(38px, 7vw, 52px);\n  line-height: 1.1;\n  margin-bottom: 8px;\n}\n\n/* 上方摘要保留卡片 */\n.signal106-focus-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n  margin: 22px 0 28px;\n}\n\n.signal106-focus {\n  border-radius: 20px;\n  padding: 16px;\n  min-height: 188px;\n  border: 1.5px solid #e8eef6;\n  background: #fff;\n  overflow: hidden;\n}\n\n.signal106-focus.red {\n  background: #fff7f8;\n  border-color: #f5ccd2;\n}\n\n.signal106-focus.green {\n  background: #f2fffa;\n  border-color: #bfe8da;\n}\n\n.signal106-focus-title {\n  font-size: clamp(19px, 4.5vw, 24px);\n  font-weight: 950;\n  margin-bottom: 8px;\n}\n\n.signal106-focus.red .signal106-focus-title {\n  color: #df5662;\n}\n\n.signal106-focus.green .signal106-focus-title {\n  color: #25a67d;\n}\n\n.signal106-focus-name {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  font-size: clamp(20px, 4.9vw, 25px);\n  font-weight: 950;\n  color: #172033;\n  white-space: nowrap;\n}\n\n.signal106-focus-name b {\n  font-size: 16px;\n  color: #8a96a8;\n}\n\n.signal106-focus-price {\n  font-size: clamp(30px, 7vw, 39px);\n  font-weight: 950;\n  line-height: 1.08;\n  margin: 5px 0 8px;\n  color: #df5662;\n  white-space: nowrap;\n}\n\n.signal106-focus-price span {\n  font-size: clamp(16px, 3.7vw, 20px);\n}\n\n.signal106-focus-sub {\n  display: grid;\n  gap: 2px;\n  font-size: 14px;\n  font-weight: 900;\n  color: #8190a4;\n}\n\n.signal106-focus-sub b {\n  font-weight: 950;\n}\n\n.signal106-detail h3 {\n  font-size: clamp(31px, 6.4vw, 42px);\n  line-height: 1.15;\n  margin: 8px 0 14px;\n}\n\n.signal106-pill-row {\n  display: flex;\n  gap: 10px;\n  overflow-x: auto;\n  -webkit-overflow-scrolling: touch;\n  padding: 2px 0 10px;\n  scrollbar-width: none;\n}\n\n.signal106-pill-row::-webkit-scrollbar {\n  display: none;\n}\n\n.signal106-pill {\n  flex: 0 0 auto;\n  border-radius: 999px;\n  border: 2px solid #cbd5e1;\n  background: #fff;\n  color: #667386;\n  font-size: 20px;\n  font-weight: 950;\n  padding: 10px 15px;\n  min-height: 44px;\n}\n\n.signal106-pill b {\n  margin-left: 5px;\n}\n\n.signal106-pill.status.新增.active {\n  color: #b99a00;\n  border-color: #c7aa00;\n  background: #fffdea;\n}\n\n.signal106-pill.status.刪除.active {\n  color: #6b7280;\n  border-color: #a7b0bd;\n  background: #f8fafc;\n}\n\n.signal106-pill.status.加碼.active {\n  color: #df5662;\n  border-color: #df5662;\n  background: #fff7f8;\n}\n\n.signal106-pill.status.減碼.active {\n  color: #22a77d;\n  border-color: #22a77d;\n  background: #f2fffa;\n}\n\n.signal106-pill.sort.active {\n  color: #2f6fcc;\n  border-color: #bfdbfe;\n  background: #eff6ff;\n}\n\n/* 明細改成真正的列表表格 */\n.signal106-header {\n  display: grid;\n  grid-template-columns: minmax(92px, 1.15fr) minmax(72px, 0.8fr) minmax(92px, 1fr) minmax(72px, 0.8fr);\n  gap: 8px;\n  align-items: center;\n  padding: 12px 10px;\n  margin-top: 2px;\n  background: #f2f4f7;\n  color: #596677;\n  font-size: 15px;\n  font-weight: 950;\n  border-radius: 12px 12px 0 0;\n}\n\n.signal106-list {\n  border-top: 1px solid #e6edf5;\n}\n\n.signal106-row {\n  display: grid;\n  grid-template-columns: minmax(92px, 1.15fr) minmax(72px, 0.8fr) minmax(92px, 1fr) minmax(72px, 0.8fr);\n  gap: 8px;\n  align-items: center;\n  border-bottom: 1px solid #e6edf5;\n  padding: 14px 10px;\n}\n\n.signal106-cell b,\n.signal106-cell span,\n.signal106-cell em {\n  display: block;\n}\n\n.signal106-cell.stock b {\n  font-size: clamp(20px, 5vw, 28px);\n  font-weight: 950;\n  color: #172033;\n  line-height: 1.1;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.signal106-cell.stock span {\n  font-size: 17px;\n  font-weight: 850;\n  color: #8b98aa;\n  margin-top: 2px;\n}\n\n.signal106-cell.quote b {\n  font-size: clamp(20px, 4.8vw, 27px);\n  font-weight: 950;\n  color: #172033;\n  line-height: 1.05;\n  white-space: nowrap;\n}\n\n.signal106-cell.quote span {\n  font-size: 16px;\n  font-weight: 950;\n  margin-top: 3px;\n  white-space: nowrap;\n}\n\n.signal106-cell.trade {\n  text-align: right;\n}\n\n.signal106-cell.trade b {\n  font-size: clamp(18px, 4.3vw, 24px);\n  font-weight: 950;\n  line-height: 1.05;\n  white-space: nowrap;\n}\n\n.signal106-cell.trade span {\n  font-size: 16px;\n  font-weight: 950;\n  margin-top: 4px;\n  white-space: nowrap;\n}\n\n.signal106-cell.action {\n  text-align: right;\n}\n\n.signal106-status {\n  display: inline-flex !important;\n  justify-content: center;\n  border-radius: 999px;\n  padding: 5px 9px;\n  font-size: 15px;\n  font-weight: 950;\n  background: #eef2f7;\n  color: #64748b;\n  white-space: nowrap;\n}\n\n.signal106-status.新增 {\n  background: #fff6bf;\n  color: #b59a00;\n}\n\n.signal106-status.加碼 {\n  background: #ffecef;\n  color: #df5662;\n}\n\n.signal106-status.減碼,\n.signal106-status.刪除 {\n  background: #eafaf4;\n  color: #25a67d;\n}\n\n.signal106-cell.action em {\n  font-style: normal;\n  color: #667386;\n  font-size: 14px;\n  font-weight: 900;\n  margin-top: 5px;\n  white-space: nowrap;\n}\n\n.signal106-empty,\n.signal106-empty-list {\n  color: #7f8da0;\n  font-size: 18px;\n  font-weight: 900;\n  padding: 10px 0;\n}\n\n.signal106-empty-list {\n  border: 1px dashed #d6e0ec;\n  border-radius: 16px;\n  padding: 22px;\n}\n\n.signal106-page .up {\n  color: #df5662 !important;\n}\n\n.signal106-page .down {\n  color: #25a67d !important;\n}\n\n.signal106-page .flat {\n  color: #7f8da0 !important;\n}\n\n@media (max-width: 430px) {\n  .signal106-focus-grid {\n    gap: 10px;\n  }\n\n  .signal106-focus {\n    padding: 14px 12px;\n    min-height: 178px;\n  }\n\n  .signal106-focus-sub {\n    font-size: 13px;\n  }\n\n  .signal106-pill {\n    font-size: 18px;\n    padding: 9px 13px;\n  }\n\n  .signal106-header {\n    grid-template-columns: minmax(88px, 1.12fr) minmax(68px, 0.76fr) minmax(86px, 0.96fr) minmax(68px, 0.74fr);\n    gap: 6px;\n    padding: 10px 8px;\n    font-size: 13px;\n  }\n\n  .signal106-row {\n    grid-template-columns: minmax(88px, 1.12fr) minmax(68px, 0.76fr) minmax(86px, 0.96fr) minmax(68px, 0.74fr);\n    gap: 6px;\n    padding: 13px 8px;\n  }\n\n  .signal106-cell.stock b {\n    font-size: 22px;\n  }\n\n  .signal106-cell.stock span {\n    font-size: 16px;\n  }\n\n  .signal106-cell.quote b {\n    font-size: 22px;\n  }\n\n  .signal106-cell.quote span,\n  .signal106-cell.trade span {\n    font-size: 15px;\n  }\n\n  .signal106-cell.trade b {\n    font-size: 19px;\n  }\n\n  .signal106-status {\n    font-size: 14px;\n    padding: 5px 8px;\n  }\n\n  .signal106-cell.action em {\n    font-size: 13px;\n  }\n}\n' + "\n", encoding="utf-8")

